var card = new Border
{
    Width = 380,
    Padding = new Thickness(20),
    CornerRadius = new CornerRadius(20),
    Background = AppKit.Brush(ArcTokens.Surface),
    BorderBrush = AppKit.Brush(ArcTokens.Border),
    BorderThickness = new Thickness(1),
    BoxShadow = AppKit.Shadow(ArcTokens.ShadowRaised),
    Child = host
};

host.Content = new StackPanel
{
    Spacing = 12,
    Children =
    {
        new TextBlock { Text = "Sign in to Northwind", Classes = { "arc-subtitle" } },
        AppKit.Providers(provider => Go(2)),
        AppKit.Field("Work email", AppKit.Input("maya@northwind.co", email, value => email = value)),
        AppKit.Btn("Email me a code", ArcButtonVariant.Primary, ArcButtonSize.Md, SendCode, height: 40, stretch: true),
        AppKit.Btn("Sign in with a passkey", ArcButtonVariant.Ghost, ArcButtonSize.Md, Passkey, height: 36, stretch: true)
    }
};

return AppKit.Screen(new Panel { Children = { AppKit.Wash(ArcGlassScene.Studio), card } }, 508);
